typedef unsigned long long U;typedef unsigned __int128 B;extern void*calloc(unsigned long,unsigned long);extern void free(void*);extern int printf(const char*,...);
void emit(B x){char s[60];int i=0;do{s[i++]=48+x%10;x/=10;}while(x);while(i)printf("%c",s[--i]);}
int run(int n,int model){if(n==0){printf("n 0 model %d count 1 overflow 0\n",model);return 0;}U states=1ull<<(2*n+2);B*a=calloc(states,sizeof(B)),*b=calloc(states,sizeof(B));int overflow=0;for(U s=0;s<states;s++)a[s]=1;for(int row=0;row<n;row++){for(int col=0;col<n;col++){for(U s=0;s<states;s++)b[s]=0;int shift=2*(col+1);for(U s=0;s<states;s++){B v=a[s];if(!v)continue;int l=s&3,d=(s>>shift)&3;for(int t=0;t<4;t++)for(int r=0;r<4;r++){int ok;if(model==0||row==col)ok=l!=d&&l!=t&&l!=r&&d!=t&&d!=r&&t!=r;else ok=(l==d&&t==r&&l!=t)||(t==d&&l==r&&t!=l);if(ok){U ss=(s&~((3ull<<shift)|3ull))|((U)t<<shift)|r;B old=b[ss];b[ss]+=v;if(b[ss]<old)overflow=1;}}}B*tmp=a;a=b;b=tmp;}if(row<n-1){for(U s=0;s<states;s+=4){B v=0;for(int j=0;j<4;j++){B old=v;v+=a[s+j];if(v<old)overflow=1;}for(int l=0;l<4;l++)a[s+l]=v;}}}B result=0;for(U s=0;s<states;s++){B old=result;result+=a[s];if(result<old)overflow=1;}printf("n %d model %d count ",n,model);emit(result);printf(" overflow %d\n",overflow);free(a);free(b);return overflow;}
